import { useEffect, useState } from "react";
import { View, ScrollView, Alert } from "react-native";
import ApprovalCard from "@/components/ApprovalCard";
import { fetchApprovedRCLeaveForms, fetchRCLeaveForms, updateRCLeaveFormStatus } from "@/utils/rc/RCLeaveFormApprovalApi";
import DeclineComment from "@/components/modals/DeclineComment";
import ModalCallable from "@/components/modals/ModalCallable";
import { getLeaveBadgeStatus } from "@/utils/getBadgeStatus";
import EmptyPage from "@/components/EmptyPage";
import useLoadingStore from "@/stores/loadingStore";
import TabSwitch from "@/components/TabSwitch";

export default function LeaveFormPage() {
  const [leaveForms, setLeaveForms] = useState<any[]>([]);
  const [approvedLeaveForms, setApprovedLeaveForms] = useState<any[]>([]);
  const [modalVisible, setModalVisible] = useState(false);
  const [modalMsg, setModalMsg] = useState("");
  const [rejectModalVisible, setRejectModalVisible] = useState(false);
  const [selectedLeaveId, setSelectedLeaveId] = useState<number | null>(null);

  const setLoading = useLoadingStore((state) => state.setLoading);
  const [activeTab, setActiveTab] = useState<"pending" | "approved">("pending")

  const getLeaveForms = async () => {
    setLoading(true);
    try {
      const data = await fetchRCLeaveForms();
      setLeaveForms(data);
    } catch (err: any) {
      window.alert(["Error", err.message || "Failed to fetch leave forms"].filter(Boolean).join("\n"));
      setLeaveForms([]);
    }
    setLoading(false);
  };

  const getApprovedLeaveForms = async () => {
    setLoading(true);
    try {
      const data = await fetchApprovedRCLeaveForms();
      setApprovedLeaveForms(data);
    } catch (err: any) {
      window.alert(["Error", err.message || "Failed to fetch leave forms"].filter(Boolean).join("\n"));
      setApprovedLeaveForms([]);
    }
    setLoading(false);
  };

  useEffect(() => {
    getLeaveForms();
  }, []);

  useEffect(() => {
    getApprovedLeaveForms()
  }, [])

  const handleDecision = async (leaveFormId: number, approve: boolean, comment?: string) => {
    setLoading(true);
    try {
      await updateRCLeaveFormStatus(leaveFormId, approve, comment);
      setModalMsg(approve ? "Leave form approved successfully!" : "Leave form rejected successfully!");
      setModalVisible(true);
      await getLeaveForms();
    } catch (err: any) {
      window.alert(["Error", err.message || "Failed to update leave form status"].filter(Boolean).join("\n"));
    }
    setLoading(false);
  };

  const handleDecline = (leaveFormId: number) => {
    setSelectedLeaveId(leaveFormId);
    setRejectModalVisible(true);
  };

  const submitRejection = (reason: string) => {
    if (!reason.trim()) {
      window.alert("Error\nPlease provide a reason for rejection.");
      return;
    }
    handleDecision(
      selectedLeaveId!,
      false,
      `${reason.trim()} (Rejected by RC)`
    );
    setRejectModalVisible(false);
  };

  return (
    <View style={{ flex: 1, backgroundColor: "#fff", padding: 12 }}>
      <ModalCallable
        show={modalVisible}
        onClose={() => setModalVisible(false)}
        title="Success"
        message={modalMsg}
      />
      <DeclineComment
        visible={rejectModalVisible}
        onClose={() => setRejectModalVisible(false)}
        onSubmit={submitRejection}
        title="Reason for Rejection"
        placeholder="Enter reason for rejection"
        submitLabel="Submit"
        cancelLabel="Cancel"
      />
      <TabSwitch
        tabs={[
          {label : "Pending", value : "pending"},
          {label : "Approved", value : "approved"}
        ]}
        activeTab={activeTab}
        onTabChange={setActiveTab}
      />
      {activeTab === "pending" && (
        leaveForms.length === 0 ? (
          <EmptyPage
            title="No leave forms"
            description="There are currently no leave forms pending approval."
          />
        ) : (
            <ScrollView>
              {leaveForms.map((item) => {
                const leave = item.leave_form;
                const student = item.student;
                return (
                  <ApprovalCard
                    key={leave.id}
                    title={`${student.name} (${leave.roll_number})`}
                    subTitle={`${leave.leave_type} | ${leave.from_date} to ${leave.to_date}`}
                    badge={getLeaveBadgeStatus(leave.status)}
                    data={{
                      "Student Name": student.name,
                      "Roll Number": leave.roll_number,
                      "Course": student.course,
                      "Branch": student.branch,
                      "Semester": student.semester,
                      "Room Number": student.roomNumber,
                      "Leave Type": leave.leave_type,
                      "From": leave.from_date,
                      "To": leave.to_date,
                      "Reason": leave.reason,
                      "Address of Stay": leave.address_of_stay,
                      "Emergency Contact": leave.mobile,
                      "Email": leave.email,
                      "Status": leave.status === "0"
                          ? "Pending"
                          : leave.status 
                    }}
                    onApprove={() => handleDecision(leave.id, true)}
                    onDecline={() => handleDecline(leave.id)}
                  />
                );
              })}
            </ScrollView>
          )
      )}

      {activeTab === "approved" && (
        approvedLeaveForms.length === 0 ? (
          <EmptyPage
            title="No Approved leave forms"
            description="There are no approved Leaves by You"
          />
        ) : (
            <ScrollView>
              {approvedLeaveForms.map((item) => {
                const leave = item.leave_form;
                const student = item.student;
                return (
                  <ApprovalCard
                    key={leave.id}
                    title={`${student.name} (${leave.roll_number})`}
                    subTitle={`${leave.leave_type} | ${leave.from_date} to ${leave.to_date}`}
                    badge={getLeaveBadgeStatus(leave.status)}
                    data={{
                      "Student Name": student.name,
                      "Roll Number": leave.roll_number,
                      "Course": student.course,
                      "Branch": student.branch,
                      "Semester": student.semester,
                      "Room Number": student.roomNumber,
                      "Leave Type": leave.leave_type,
                      "From": leave.from_date,
                      "To": leave.to_date,
                      "Reason": leave.reason,
                      "Address of Stay": leave.address_of_stay,
                      "Emergency Contact": leave.mobile,
                      "Email": leave.email,
                      "Status": leave.status === "0"
                          ? "Pending"
                          : leave.status 
                    }}
                  />
                );
              })}
            </ScrollView>
          )
      )}
    </View>
  );
}